draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 100, 0, 2 * Math.PI);
  ctx.stroke();
  for (let i = 0; i < 5; i++) {
    ctx.save();
    ctx.translate(W/2, H/2);
    ctx.rotate(i * Math.PI / 2.5 + Math.sin(t + i));
    ctx.beginPath();
    ctx.arc(0, -50, 20, 0, 2 * Math.PI);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(0, -50);
    ctx.lineTo(0, -100);
    ctx.stroke();
    ctx.restore();
  }
  ctx.restore();
}
